text:
{
  "questions": [
    {
      "n": 1,
      "start": "Lorsqu’une allocation de formation est versée",
      "end": "directement à un enfant majeur en formation"
    },
    {
      "n": 2,
      "start": "Dans une telle situation, les allocations doivent-elles",
      "end": "être déclarées dans la taxation fiscale du parent, dans celle de l’enfant majeur ou dans les deux ?"
    },
    {
      "n": 3,
      "start": "Le fait que l’enfant majeur en formation ne vive plus",
      "end": "au domicile de ses parents modifie-t-il l’analyse fiscale ou la détermination du bénéficiaire fiscal des allocations de formation ?"
    },
    {
      "n": 4,
      "start": "Le fait que l’enfant majeur en formation soit marié",
      "end": "modifie-t-il le traitement fiscal des allocations de formation versées directement à ce dernier ?"
    },
    {
      "n": 5,
      "start": "Le versement direct à l’enfant majeur en formation a-t-il",
      "end": "des conséquences sur les déductions fiscales accordées aux parents pour enfant à charge ou enfant en formation, notamment lorsque l’enfant ne vit plus au domicile familial ou est marié ?"
    },
    {
      "n": 6,
      "start": "Existe-t-il des directives cantonales ou des pratiques administratives",
      "end": "harmonisées entre les caisses d’allocations familiales et l’administration fiscale genevoise concernant ces différentes situations ?"
    },
    {
      "n": 7,
      "start": "Le Conseil d’Etat envisage-t-il de clarifier, le cas échéant,",
      "end": "les conséquences fiscales liées au versement direct des allocations de formation à un enfant majeur ?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Lorsque l’allocation de formation est allouée directement",
      "end": "à l’enfant majeur par la caisse d’allocation familiale, le sujet fiscal est l’enfant majeur."
    },
    {
      "n": 2,
      "start": "Dans cette situation, les allocations doivent-elles",
      "end": "être déclarées chez l’enfant majeur."
    },
    {
      "n": 3,
      "start": "Non.",
      "end": null
    },
    {
      "n": 4,
      "start": "Non.",
      "end": null
    },
    {
      "n": 5,
      "start": "Oui, les allocations de formation allouées et imposées directement chez",
      "end": "l’enfant majeur sont prises en considération dans le calcul des revenus bruts servant à la détermination de la déduction pour charge de famille."
    },
    {
      "n": 6,
      "start": "Il n’existe pas de directive cantonale ou de pratique administrative",
      "end": "particulière."
    },
    {
      "n": 7,
      "start": "A notre connaissance, cette thématique ne soulève pas de question",
      "end": "particulière. L’administration fiscale cantonale évaluera toutefois la nécessité de compléter le guide de la déclaration concernant cette thématique."
    }
  ],
  "submitter": "Ana Roch",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "A notre connaissance, cette thématique ne soulève pas de question",
    "end": "particulière. L’administration fiscale cantonale évaluera toutefois la nécessité de compléter le guide de la déclaration concernant cette thématique."
  }
}
